using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "GainTwoEffectsAction", menuName = "Data/Battle/Battle Actions/Any/GainTwoEffects Action")]
public class GainTwoEffectsAction : BattleAction
{
	[Header("Gain Two Effects Action")]
	[SerializeField]
	private BattleAction firstEffectAction;

	[SerializeField]
	private bool overrideFirstEffectAmount;

	[SerializeField]
	[ShowIf("overrideFirstEffectAmount")]
	private int firstEffectAmountToOverride;

	[SerializeField]
	private BattleAction secondEffectAction;

	[SerializeField]
	private bool overrideSecondEffectAmount;

	[SerializeField]
	[ShowIf("overrideSecondEffectAmount")]
	private int secondEffectAmountToOverride;

	[SerializeField]
	private bool useEffectDescription;

	[SerializeField]
	private bool putFirstAndSecondDescriptionInTheSameLine;

	[Header("Orion")]
	[SerializeField]
	private bool enableStarRequirement;

	[SerializeField]
	[ShowIf("enableStarRequirement")]
	private StarRequirementAction starRequirementAction;

	public BattleAction FirstEffectAction => firstEffectAction;

	public bool OverrideFirstEffectAmount => overrideFirstEffectAmount;

	public int FirstEffectAmountToOverride => firstEffectAmountToOverride;

	public BattleAction SecondEffectAction => secondEffectAction;

	public bool OverrideSecondEffectAmount => overrideSecondEffectAmount;

	public int SecondEffectAmountToOverride => secondEffectAmountToOverride;

	public bool UseEffectDescription => useEffectDescription;

	public bool PutFirstAndSecondDescriptionInTheSameLine => putFirstAndSecondDescriptionInTheSameLine;

	public bool EnableStarRequirement => enableStarRequirement;

	public StarRequirementAction StarRequirementAction => starRequirementAction;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		bool result = true;
		if (enableStarRequirement)
		{
			result = starRequirementAction.CheckConditionToBeCasted(actionValue);
		}
		return result;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (overrideFirstEffectAmount)
		{
			firstEffectAction.CastTargetAmount(target, firstEffectAmountToOverride, source);
		}
		else
		{
			firstEffectAction.CastTargetAmount(target, amount, source);
		}
		if (overrideSecondEffectAmount)
		{
			secondEffectAction.CastTargetAmount(target, secondEffectAmountToOverride, source);
		}
		else
		{
			secondEffectAction.CastTargetAmount(target, amount, source);
		}
	}
}
